const sub = (a, b) => ({ x: a.x - b.x, y: a.y - b.y });   // b → a 로 가는 화살표
const len = (v) => Math.hypot(v.x, v.y);                   // 길이
const norm = (v) => { const l = len(v) || 1; return { x: v.x / l, y: v.y / l }; };
const dot = (a, b) => a.x * b.x + a.y * b.y;

// 적을 향하는 방향
const 방향 = norm(sub(적.위치, 나.위치));
나.위치.x += 방향.x * 속도 * dt;
나.위치.y += 방향.y * 속도 * dt;

const 시야각 = 60; // 도
let mx = 200, my = 90;
addEventListener('mousemove', (e) => { mx = e.clientX; my = e.clientY; });
function frame(now) {
  ctx.clearRect(0, 0, W(), H());
  const cx = W() / 2, cy = H() / 2;
  const dir = { x: Math.cos(now / 900), y: Math.sin(now / 900) };
  const to = { x: mx - cx, y: my - cy };
  const len = Math.hypot(to.x, to.y) || 1;
  const dot = (dir.x * to.x + dir.y * to.y) / len;
  const 보인다 = dot > Math.cos((시야각 / 2) * Math.PI / 180);
  ctx.strokeStyle = '#666'; ctx.beginPath(); ctx.moveTo(cx, cy);
  ctx.lineTo(cx + dir.x * 70, cy + dir.y * 70); ctx.stroke();
  ctx.fillStyle = 보인다 ? '#4ade80' : '#f87171';
  ctx.beginPath(); ctx.arc(mx, my, 8, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = '#eee'; ctx.font = '13px system-ui';
  ctx.fillText(보인다 ? '시야 안 (dot ' + dot.toFixed(2) + ')' : '시야 밖 (dot ' + dot.toFixed(2) + ')', 14, 22);
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);

